const results = [];

for (const item of $input.all()) {
  const submittedDate = new Date(item.json.Date);

  // Reminder date = submission date + 25 days
  const reminderDate = new Date(submittedDate);
  reminderDate.setDate(reminderDate.getDate() + 25);

  // Exam date = submission date + 30 days
  const examDate = new Date(submittedDate);
  examDate.setDate(examDate.getDate() + 30);

  results.push({
    json: {
      ...item.json,
      submissionDate: submittedDate.toISOString().split('T')[0],   // YYYY-MM-DD
      reminderDate: reminderDate.toISOString().split('T')[0],       // YYYY-MM-DD
      examDate: examDate.toISOString().split('T')[0]                // YYYY-MM-DD
    }
  });
}

return results;

